def tau(n):
    if n == 1:
        return 1
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return 1

def tau_n_pow_12(n):
    if n == 1:
        return 1
    # Get prime factorization of n
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    # Calculate tau(n^12)
    # If n = p1^a1 * p2^a2 ..., then n^12 = p1^(12*a1) * p2^(12*a2) ...
    # tau(n^12) = (12*a1 + 1) * (12*a2 + 1) * ...
    tau_val = 1
    for exponent in factors.values():
        tau_val *= (12 * exponent + 1)
    return tau_val

